/** About 5 min warm-up + 2.5 min a set, the app's estimate. */
export function setBudget(minutes: number): number {
  return Math.max(8, Math.floor((minutes - 5) / 2.5));
}

export type WeekKind = 'build' | 'deload';
export interface WeekPlan {
  week: number;
  kind: WeekKind;
  /** Target reps in reserve on working sets; the deload is 3+. */
  rir: number;
}

/**
 * Which weeks deload. A reduced week, never full rest: a week off cost
 * strength in Coleman 2024. Beginners skip a short block's deload.
 */
export function deloadWeeks(weeks: number, experience: PlanExperience): number[] {
  if (weeks < 4) return [];
  if (experience === 'beginner') return weeks >= 6 ? [weeks] : [];
  if (weeks < 8) return [weeks];
  const out: number[] = [];
  for (let w = 4; w <= weeks; w += 4) out.push(w);
  if (out[out.length - 1] !== weeks && weeks - out[out.length - 1]! >= 3) out.push(weeks);
  return out;
}

/**
 * Effort ramp inside each block: start about 3 reps short of failure and end
 * about 1 short in the last hard week (PROGRAMMING §3).
 */
export function weekPlan(weeks: number, experience: PlanExperience): WeekPlan[] {
  const deloads = new Set(deloadWeeks(weeks, experience));
  const out: WeekPlan[] = [];
  let blockStart = 1;
  for (let w = 1; w <= weeks; w++) {
    if (deloads.has(w)) {
      out.push({ week: w, kind: 'deload', rir: 3 });
      blockStart = w + 1;
      continue;
    }
    let blockEnd = w;
    while (blockEnd + 1 <= weeks && !deloads.has(blockEnd + 1)) blockEnd++;
    const len = blockEnd - blockStart + 1;
    const pos = w - blockStart;
    const rir = len <= 1 ? 2 : Math.round(3 - (2 * pos) / (len - 1));
    out.push({ week: w, kind: 'build', rir });
  }
  return out;
}

